;_detectNavbar&quot;,&quot;_createPopper&quot;,&quot;focus&quot;,&quot;_completeHide&quot;,&quot;destroy&quot;,&quot;update&quot;,&quot;Popper&quot;,&quot;referenceElement&quot;,&quot;_getPopperConfig&quot;,&quot;createPopper&quot;,&quot;_getPlacement&quot;,&quot;parentDropdown&quot;,&quot;isEnd&quot;,&quot;_getOffset&quot;,&quot;popperData&quot;,&quot;defaultBsPopperConfig&quot;,&quot;placement&quot;,&quot;modifiers&quot;,&quot;options&quot;,&quot;enabled&quot;,&quot;_selectMenuItem&quot;,&quot;clearMenus&quot;,&quot;openToggles&quot;,&quot;context&quot;,&quot;composedPath&quot;,&quot;isMenuTarget&quot;,&quot;dataApiKeydownHandler&quot;,&quot;isInput&quot;,&quot;isEscapeEvent&quot;,&quot;isUpOrDownEvent&quot;,&quot;getToggleButton&quot;,&quot;stopPropagation&quot;,&quot;EVENT_MOUSEDOWN&quot;,&quot;className&quot;,&quot;clickCallback&quot;,&quot;rootElement&quot;,&quot;Backdrop&quot;,&quot;_isAppended&quot;,&quot;_append&quot;,&quot;_getElement&quot;,&quot;_emulateAnimation&quot;,&quot;backdrop&quot;,&quot;createElement&quot;,&quot;append&quot;,&quot;EVENT_FOCUSIN&quot;,&quot;EVENT_KEYDOWN_TAB&quot;,&quot;TAB_NAV_BACKWARD&quot;,&quot;autofocus&quot;,&quot;trapElement&quot;,&quot;FocusTrap&quot;,&quot;_isActive&quot;,&quot;_lastTabNavDirection&quot;,&quot;activate&quot;,&quot;_handleFocusin&quot;,&quot;_handleKeydown&quot;,&quot;deactivate&quot;,&quot;elements&quot;,&quot;shiftKey&quot;,&quot;SELECTOR_FIXED_CONTENT&quot;,&quot;SELECTOR_STICKY_CONTENT&quot;,&quot;PROPERTY_PADDING&quot;,&quot;PROPERTY_MARGIN&quot;,&quot;ScrollBarHelper&quot;,&quot;getWidth&quot;,&quot;documentWidth&quot;,&quot;clientWidth&quot;,&quot;innerWidth&quot;,&quot;width&quot;,&quot;_disableOverFlow&quot;,&quot;_setElementAttributes&quot;,&quot;calculatedValue&quot;,&quot;reset&quot;,&quot;_resetElementAttributes&quot;,&quot;isOverflowing&quot;,&quot;_saveInitialAttribute&quot;,&quot;overflow&quot;,&quot;styleProperty&quot;,&quot;scrollbarWidth&quot;,&quot;_applyManipulationCallback&quot;,&quot;setProperty&quot;,&quot;actualValue&quot;,&quot;removeProperty&quot;,&quot;callBack&quot;,&quot;EVENT_HIDE_PREVENTED&quot;,&quot;EVENT_RESIZE&quot;,&quot;EVENT_CLICK_DISMISS&quot;,&quot;EVENT_MOUSEDOWN_DISMISS&quot;,&quot;EVENT_KEYDOWN_DISMISS&quot;,&quot;CLASS_NAME_OPEN&quot;,&quot;CLASS_NAME_STATIC&quot;,&quot;Modal&quot;,&quot;_dialog&quot;,&quot;_backdrop&quot;,&quot;_initializeBackDrop&quot;,&quot;_focustrap&quot;,&quot;_initializeFocusTrap&quot;,&quot;_scrollBar&quot;,&quot;_adjustDialog&quot;,&quot;_showElement&quot;,&quot;_hideModal&quot;,&quot;handleUpdate&quot;,&quot;scrollTop&quot;,&quot;modalBody&quot;,&quot;transitionComplete&quot;,&quot;_triggerBackdropTransition&quot;,&quot;event2&quot;,&quot;_resetAdjustments&quot;,&quot;isModalOverflowing&quot;,&quot;scrollHeight&quot;,&quot;clientHeight&quot;,&quot;initialOverflowY&quot;,&quot;overflowY&quot;,&quot;isBodyOverflowing&quot;,&quot;paddingLeft&quot;,&quot;paddingRight&quot;,&quot;showEvent&quot;,&quot;alreadyOpen&quot;,&quot;CLASS_NAME_SHOWING&quot;,&quot;CLASS_NAME_HIDING&quot;,&quot;OPEN_SELECTOR&quot;,&quot;scroll&quot;,&quot;Offcanvas&quot;,&quot;blur&quot;,&quot;completeCallback&quot;,&quot;position&quot;,&quot;DefaultAllowlist&quot;,&quot;a&quot;,&quot;area&quot;,&quot;b&quot;,&quot;br&quot;,&quot;col&quot;,&quot;code&quot;,&quot;dd&quot;,&quot;div&quot;,&quot;dl&quot;,&quot;dt&quot;,&quot;em&quot;,&quot;hr&quot;,&quot;h1&quot;,&quot;h2&quot;,&quot;h3&quot;,&quot;h4&quot;,&quot;h5&quot;,&quot;h6&quot;,&quot;i&quot;,&quot;li&quot;,&quot;ol&quot;,&quot;p&quot;,&quot;pre&quot;,&quot;s&quot;,&quot;small&quot;,&quot;span&quot;,&quot;sub&quot;,&quot;sup&quot;,&quot;strong&quot;,&quot;u&quot;,&quot;ul&quot;,&quot;uriAttributes&quot;,&quot;SAFE_URL_PATTERN&quot;,&quot;allowedAttribute&quot;,&quot;attribute&quot;,&quot;allowedAttributeList&quot;,&quot;attributeName&quot;,&quot;nodeName&quot;,&quot;nodeValue&quot;,&quot;attributeRegex&quot;,&quot;some&quot;,&quot;regex&quot;,&quot;allowList&quot;,&quot;co